60→                            if (($capability === ProvidesGrants::class && ! $item instanceof Grant) || ($capability === ProvidesRoleGrants::class && ! $item instanceof RoleContribution)) {
                                throw new InvalidSourceContributionException('Unexpected contribution type.');
                            }

